--This file was generated by AI

-- installer.lua
-- Installs the latest release of this project from GitHub and configures it.
--
-- Run it with:
--   wget run https://raw.githubusercontent.com/<user>/<repo_name>/main/installer.lua

local repo           = "https://github.com/Sirc23/RASCL/"
local branch         = "main"       -- the branch that holds the releases folder
local releasesFolder = "releases"

-- Config files that get edited after the download, relative to the install location
local SERVER_CONFIG = "rascl/tables/server_config.csv"
local CLIENT_CONFIG = "rascl/tables/client_config.csv"

-- The config CSVs use the single byte 0xF7 (the "÷" glyph in ComputerCraft's
-- character set) as their delimiter. It is NOT UTF-8, so every file is
-- downloaded, read and written in binary mode to keep it byte-for-byte intact.
local DELIM = "\247"

local API_HEADERS = {
	["User-Agent"] = "ComputerCraft-Installer",
	["Accept"] = "application/vnd.github+json",
}
local RAW_HEADERS = { ["User-Agent"] = "ComputerCraft-Installer" }

------------------------------------------------------------------------
-- Helpers
------------------------------------------------------------------------

local function trim(s)
	return (s or ""):match("^%s*(.-)%s*$")
end

-- Percent-encodes everything in a path except letters, digits, "-._~" and "/"
local function encodePath(path)
	return (path:gsub("[^%w%-%._~/]", function(c)
		return ("%%%02X"):format(c:byte())
	end))
end

-- GET a URL in binary mode, retrying on transient failures.
-- Returns body, or nil, errorMessage, httpStatusCode
local function httpGet(url, headers)
	local lastErr, code
	for _ = 1, 3 do
		local res, err, failRes = http.get(url, headers, true)
		if res then
			local body = res.readAll() or ""
			res.close()
			return body
		end
		lastErr = err or "unknown error"
		code = nil
		if failRes then
			code = failRes.getResponseCode()
			failRes.close()
		end
		-- A 4xx answer won't change by asking again
		if code and code >= 400 and code < 500 then break end
		sleep(1)
	end
	return nil, lastErr, code
end

-- GET from the GitHub API and decode the JSON reply
local function apiGet(path)
	local body, err, code = httpGet("https://api.github.com/repos/" .. path, API_HEADERS)
	if not body then
		local msg = "GitHub request failed: " .. tostring(err)
		if code == 403 or code == 429 then
			msg = msg .. "\nThis is probably GitHub's rate limit (60 requests per hour per IP"
				.. " address, shared by everyone on this server). Try again later."
		end
		error(msg, 0)
	end
	local data, jsonErr = textutils.unserialiseJSON(body)
	if data == nil then
		error("Could not read GitHub's reply: " .. tostring(jsonErr), 0)
	end
	return data
end

-- Splits "a1.10.3" into a prefix letter ("a") and numbers ({1, 10, 3})
local function parseVersion(name)
	local nums = {}
	for n in name:sub(2):gmatch("%d+") do
		nums[#nums + 1] = tonumber(n)
	end
	return name:sub(1, 1), nums
end

-- Orders versions so the newest sorts last. "a" (alpha) sorts before "v"
-- (release), and the numbers are compared as numbers, so a1.10.0 comes
-- after a1.9.0 (a plain string sort would put it before).
local function versionLess(a, b)
	local prefixA, numsA = parseVersion(a)
	local prefixB, numsB = parseVersion(b)
	if prefixA ~= prefixB then return prefixA < prefixB end
	for i = 1, math.max(#numsA, #numsB) do
		local x, y = numsA[i] or 0, numsB[i] or 0
		if x ~= y then return x < y end
	end
	return a < b
end

-- Returns nil if the hostname is fine, otherwise a sentence explaining why not
local function hostnameProblem(s)
	if #s == 0 then
		return "The hostname can't be empty."
	end
	if #s > 16 then
		return ("The hostname is %d characters long; the maximum is 16."):format(#s)
	end
	local bad = s:gsub("[%w_%-]", "")
	if #bad > 0 then
		local seen, list = {}, {}
		for c in bad:gmatch(".") do
			if not seen[c] then
				seen[c] = true
				list[#list + 1] = (c == " ") and "space" or ("'" .. c .. "'")
			end
		end
		return "The hostname contains characters that aren't allowed: " .. table.concat(list, ", ")
			.. ". Use only letters, numbers, underscores and dashes."
	end
	return nil
end

-- Writes data to path (binary), creating parent folders as needed
local function writeFile(path, data)
	local dir = fs.getDir(path)
	if dir ~= "" and not fs.exists(dir) then
		fs.makeDir(dir)
	end
	local handle, err = fs.open(path, "wb")
	if not handle then
		return false, "Could not write /" .. path .. ": " .. tostring(err)
	end
	handle.write(data)
	handle.close()
	return true
end

-- Sets the value for `key` in a "key<DELIM>value" CSV, leaving every other
-- byte of the file as it was. The row is added if the key isn't there yet.
local function setConfigValue(path, key, value)
	local handle = fs.open(path, "rb")
	if not handle then
		return false, "Could not open /" .. path .. " - is it part of this release?"
	end
	local content = handle.readAll() or ""
	handle.close()

	local lines, found = {}, false
	-- Appending "\n" means a file ending in a newline yields a final "" entry,
	-- so joining with "\n" below reproduces the original ending exactly.
	for line in (content .. "\n"):gmatch("(.-)\n") do
		local cr = line:match("\r$") or ""
		local body = line:sub(1, #line - #cr)
		local rowKey = body:match("^(.-)" .. DELIM)
		if rowKey == key then
			line = key .. DELIM .. value .. cr
			found = true
		end
		lines[#lines + 1] = line
	end

	if not found then
		local newRow = key .. DELIM .. value
		if lines[#lines] == "" then
			table.insert(lines, #lines, newRow)
		else
			lines[#lines + 1] = newRow
		end
	end

	return writeFile(path, table.concat(lines, "\n"))
end

------------------------------------------------------------------------
-- Prompts
------------------------------------------------------------------------

local function promptInstallDir()
	while true do
		write("Install location (blank for the root directory): ")
		local dir = fs.combine("/", trim(read()))
		if dir == ".." or dir:sub(1, 3) == "../" then
			printError("That location is outside this computer's file system.")
		elseif fs.exists(dir) and not fs.isDir(dir) then
			printError("/" .. dir .. " is a file, not a directory.")
		elseif fs.isReadOnly(dir) then
			printError("/" .. dir .. " is read-only.")
		else
			return dir
		end
	end
end

local function promptHostname()
	while true do
		write("Hostname (letters, numbers, _ and -, up to 16 characters): ")
		local hostname = trim(read())
		local problem = hostnameProblem(hostname)
		if not problem then return hostname end
		printError(problem)
	end
end

local function promptDeviceType()
	local types = { h = "host", c = "crafter", o = "remote" }
	while true do
		write("Device type - (h)ost, (c)rafter or rem(o)te: ")
		local choice = trim(read()):lower()
		if types[choice] then return types[choice] end
		printError("Please type h, c or o.")
	end
end

------------------------------------------------------------------------
-- Installer
------------------------------------------------------------------------

local function main()
	if not http then
		error("The HTTP API is disabled, so files can't be downloaded.", 0)
	end

	local owner, name = repo:match("github%.com/([^/]+)/([^/]+)")
	if not owner then
		error("'repo' should look like https://github.com/<user>/<repo_name>/", 0)
	end
	name = name:gsub("%.git$", "")

	-- 1. Where to install
	local installDir = promptInstallDir()
	print("Installing to /" .. installDir)

	-- 2. Find the latest version
	print("Looking for the latest version...")
	local listing = apiGet(("%s/%s/contents/%s?ref=%s"):format(owner, name, releasesFolder, branch))
	local versions = {}
	for _, entry in ipairs(listing) do
		if entry.type == "dir" and entry.name:match("^[av]%d+%.%d+%.%d+$") then
			versions[#versions + 1] = entry
		end
	end
	if #versions == 0 then
		error("No release folders (named like a1.0.0 or v1.0.0) were found in '"
			.. releasesFolder .. "' on branch '" .. branch .. "'.", 0)
	end
	table.sort(versions, function(a, b) return versionLess(a.name, b.name) end)
	local latest = versions[#versions]
	print("Latest version: " .. latest.name)

	-- 3. Download every file in that version's folder
	local tree = apiGet(("%s/%s/git/trees/%s?recursive=1"):format(owner, name, latest.sha))
	if tree.truncated then
		error("This release has too many files to list in one GitHub request.", 0)
	end
	local files = {}
	for _, entry in ipairs(tree.tree or {}) do
		if entry.type == "blob" then
			files[#files + 1] = entry.path
		end
	end
	table.sort(files)
	if #files == 0 then
		error("Release " .. latest.name .. " doesn't contain any files.", 0)
	end

	local rawBase = ("https://raw.githubusercontent.com/%s/%s/"):format(owner, name)
	for i, rel in ipairs(files) do
		print(("[%d/%d] %s"):format(i, #files, rel))
		local url = rawBase .. encodePath(("%s/%s/%s/%s"):format(branch, releasesFolder, latest.name, rel))
		local data, err = httpGet(url, RAW_HEADERS)
		if not data then
			error(("Failed to download %s: %s"):format(rel, tostring(err)), 0)
		end

		-- The startup folder always goes in the root directory; everything
		-- else goes in the chosen install location.
		local dest
		if rel:sub(1, 8) == "startup/" then
			dest = rel
		else
			dest = fs.combine(installDir, rel)
		end
		local ok, writeErr = writeFile(dest, data)
		if not ok then error(writeErr, 0) end
	end
	print("Download complete.")

	-- 4. Hostname
	local hostname = promptHostname()

	-- 5. Device type
	local deviceType = promptDeviceType()

	-- 6. server_config.csv
	local ok, err = setConfigValue(fs.combine(installDir, SERVER_CONFIG), "server_hostname", hostname)
	if not ok then error(err, 0) end

	-- 7. client_config.csv
	ok, err = setConfigValue(fs.combine(installDir, CLIENT_CONFIG), "computer_type", deviceType)
	if not ok then error(err, 0) end

	-- 8. Restart
	print("Installation finished. Rebooting in 3 seconds...")
	sleep(3)
	os.reboot()
end

main()
